B.ash=new A.bs("ispat_13",B.dr,"Taraflar, bilirki\u015fi raporunun kendilerine tebli\u011f tarihinden itibaren kural olarak ka\xe7 hafta i\xe7inde raporda eksik g\xf6rd\xfckleri hususlar\u0131n bilirki\u015fiye tamamlatt\u0131r\u0131lmas\u0131n\u0131 mahkemeden isteyebilirler?",B.rb,1,"HMK m. 281/1 uyar\u0131nca taraflar, bilirki\u015fi raporunun tebli\u011fi tarihinden itibaren iki hafta i\xe7inde raporda eksik veya belirsiz g\xf6rd\xfckleri hususlar\u0131n giderilmesini yahut yeni bir bilirki\u015fi atanmas\u0131n\u0131 isteyebilirler.")
B.asu=new A.bs("gecici_08",B.eQ,"Kar\u015f\u0131 taraf dinlenmeden (yoklu\u011funda) verilen ihtiyati tedbir kararlar\u0131na kar\u015f\u0131, itiraz hakk\u0131 olanlar karar\u0131n uygulanmas\u0131 s\u0131ras\u0131nda haz\u0131r bulunmuyorlarsa, tedbirin uygulanmas\u0131na ili\u015fkin tutana\u011f\u0131n tebli\u011finden itibaren en ge\xe7 ne kadar s\xfcre i\xe7inde itiraz edebilirler?",B.rb,0,"HMK m. 394/2 uyar\u0131nca kar\u015f\u0131 taraf dinlenmeden verilmi\u015f olan ihtiyati tedbir kararlar\u0131na itiraz s\xfcresi, karar\u0131n uyguland\u0131\u011f\u0131na ili\u015fkin tutana\u011f\u0131n tebli\u011finden itibaren bir haftad\u0131r.")
